#!/usr/bin/env bash
# Prints the Homebrew formula for a release: dev/formula.sh <version> <dir>,
# where <dir> holds the release archives and their .sha256 files.
set -euo pipefail
version=$1
dir=$2
url=https://github.com/qopsc/rustFUSE/releases/download/v$version

sum() {
  local f="$dir/rustfuse-$version-$1.tar.gz.sha256"
  [ -f "$f" ] || { echo "missing $f" >&2; exit 1; }
  cut -d' ' -f1 "$f"
}

cat <<RUBY
# Generated by dev/formula.sh for each release; edit the script, not this.
class Rustfuse < Formula
  desc "Keep directories and git worktrees in sync through S3-compatible storage"
  homepage "https://github.com/qopsc/rustFUSE"
  version "$version"
  license any_of: ["MIT", "Apache-2.0"]

  on_macos do
    depends_on arch: :arm64
    url "$url/rustfuse-$version-aarch64-apple-darwin.tar.gz"
    sha256 "$(sum aarch64-apple-darwin)"
  end

  on_linux do
    on_intel do
      url "$url/rustfuse-$version-x86_64-unknown-linux-musl.tar.gz"
      sha256 "$(sum x86_64-unknown-linux-musl)"
    end
    on_arm do
      url "$url/rustfuse-$version-aarch64-unknown-linux-musl.tar.gz"
      sha256 "$(sum aarch64-unknown-linux-musl)"
    end
  end

  def install
    bin.install "rustfuse"
    # FUSE mounts through macFUSE; starts only where macFUSE is installed.
    bin.install "rustfuse-macfuse" if OS.mac?
  end

  def caveats
    on_macos do
      <<~EOS
        rustfuse mounts through the built-in NFS client. For FUSE mounts,
        install macFUSE (brew install --cask macfuse) and use rustfuse-macfuse.
      EOS
    end
  end

  test do
    assert_equal "rustfuse #{version}", shell_output("#{bin}/rustfuse --version").strip
    assert_match "Keep a directory in sync", shell_output("#{bin}/rustfuse --help")
  end
end
RUBY
